sys_script.script:
(function dedupContinuityItem(current) {
    var runId = current.getValue('run_id');
    var srcTable = current.getValue('source_table');
    var srcSysId = current.getValue('source_sys_id');
    var stageKey = current.getValue('source_stage_key');

    if (!runId || !srcTable || !srcSysId) return;

    var gr = new GlideRecord('x_2316178_contin_0_cont_item');
    gr.addQuery('run_id', runId);
    gr.addQuery('source_table', srcTable);
    gr.addQuery('source_sys_id', srcSysId);

    // Handle null stage key matching
    if (stageKey) {
        gr.addQuery('source_stage_key', stageKey);
    } else {
        gr.addNullQuery('source_stage_key');
    }

    gr.addQuery('sys_id', '!=', current.getUniqueValue());
    gr.query();

    if (gr.next()) {
        gs.addErrorMessage('A Continuity Item already exists for this run, source, and stage combination.');
        current.setAbortAction(true);
    }
})(current);
